#!/usr/bin/env bash
# Regenerates the Rust code generated by rustorb-idl -brust that is checked
# in: the mapping test of this crate, the CosNaming stubs of rustorb-naming
# and the stubs of the rustorb interop client and server. Needs idl_parser
# importable (or IDL_PARSER_DIR set to a checkout of it) and rustfmt. CI
# checks that the committed code is up to date (it runs this and git diff).
set -euo pipefail

here="$(cd "$(dirname "$0")" && pwd)"
root="$(cd "$here/../.." && pwd)"
pythonpath="$here/python"
[ -n "${IDL_PARSER_DIR:-}" ] && pythonpath="$IDL_PARSER_DIR:$pythonpath"
idl() {
  PYTHONPATH="$pythonpath${PYTHONPATH:+:$PYTHONPATH}" python3 -m rustorb_idl -brust "$@"
}

idl -C "$here/tests/generated" "$here/tests/idl/RustMapping.idl"
idl -C "$root/crates/rustorb-naming/src/idl" "$here/tests/idl/CosNaming.idl"
for f in InteropTest AnyTest ValueTest; do
  idl -I "$root/interop/idl" -C "$root/interop/impls/rustorb/src/idl" "$root/interop/idl/$f.idl"
done
